// messages (D-40): every user-facing and accessible string in one flat map.
export const messages = {
  calendarLabel: 'Calendar',
  toolbarLabel: 'Calendar navigation',
  today: 'Today',
  previous: (unit) => `Previous ${unit}`,
  next: (unit) => `Next ${unit}`,
  viewButton: (view) => `View: ${view}`,
  views: { month: 'Month', week: 'Week' },
  monthGrid: 'Month',
  allDayGrid: 'All-day events',
  timeGrid: 'Times',
  eventGroup: 'Events',
  allDay: 'All day',
  events: (n) => (n === 0 ? 'no events' : n === 1 ? '1 event' : `${n} events`),
  more: (n) => `${n} more ${n === 1 ? 'event' : 'events'}`,
  outsideMonth: (before) => (before ? 'previous month' : 'next month'),
  continuesUntil: (day) => `continues until ${day}`,
  recurring: 'Recurring',
  tentative: 'Tentative',
  readOnly: 'Read-only',
  pending: 'Pending',
  afterDstChange: 'after the daylight-saving change',
  skippedSlot: 'skipped, daylight-saving change',
  repeatedHour: (a, b) => `first or second occurrence (${a} or ${b})`,
  selected: (what) => `Selected ${what}`,
  selectionCleared: 'Selection cleared',
  notAllowed: (reason) => `not allowed: ${reason}`,
  moving: (title) =>
    `Moving ${title}. Use arrow keys to move, Enter to drop, Escape to cancel. Or click a slot to drop it there.`,
  moveCancelled: (title) => `Move cancelled. ${title} is back where it was.`,
  dropped: (name) => `Dropped. ${name}. Waiting for the app to confirm.`,
  willBecomeAllDay: 'will become an all-day event',
  willBecomeTimed: 'will become a timed event',
  menu: {
    open: 'Open',
    move: 'Move',
    details: 'Show details',
    delete: 'Delete',
  },
  menuLabel: (title) => `Actions for ${title}`,
}
